515: /// The private payload of `PropType::Opaque`. Fields are unreachable from
516: /// outside this module — the only ways to build one are `give_up` (pushes
517: /// the diagnostic that explains the degradation, then builds the value) and
518: /// `new` (for the one documented exception: `known.rs`, which has no
519: /// diagnostics channel of its own and pushes its own diagnostic separately
520: /// via `known::push_known_opaque_diagnostic` — see that function's doc
521: /// comment). Read the payload back through `raw()`/`reason()`.
522: #[derive(Debug, Clone, PartialEq)]
523: pub struct OpaqueDetail {
524:     raw: std::string::String,
525:     reason: OpaqueReason,
526: }
527: 
528: impl OpaqueDetail {
529:     #[allow(clippy::new_ret_no_self)]
530:     pub(crate) fn new(raw: impl Into<std::string::String>, reason: OpaqueReason) -> PropType {
531:         PropType::Opaque(OpaqueDetail { raw: raw.into(), reason })
532:     }
533: 
534:     /// The sanctioned "give up and record why" constructor — pushes
535:     /// `diagnostic` onto `state` before building the value, so a resolver
536:     /// call site that reaches for this can't forget to explain the
537:     /// degradation the way the old bare `PropType::Opaque { .. }` literal let
538:     /// call sites do.
539:     pub(crate) fn give_up(
540:         state: &mut ResolveState,
541:         raw: impl Into<std::string::String>,
542:         reason: OpaqueReason,
543:         diagnostic: Diagnostic,
544:     ) -> PropType {
545:         state.diagnostics.push(diagnostic);
546:         #[allow(clippy::disallowed_methods, reason = "the diagnostic is pushed on the line above")]
547:         Self::new(raw, reason)
548:     }
549: 
550:     pub(crate) fn raw(&self) -> &str {
551:         &self.raw
552:     }
553: 
554:     pub(crate) fn reason(&self) -> &OpaqueReason {
555:         &self.reason
556:     }
557: }
