560:     /// Feed `hasher` everything that tells two types apart, so equal types hash equal. The resolver shares identical
561:     /// props by this hash (`ResolutionContext::share`).
562:     pub(crate) fn structural_hash<H: std::hash::Hasher>(&self, hasher: &mut H) {
563:         use std::hash::Hash;
564:         std::mem::discriminant(self).hash(hasher);
565:         let all = |hasher: &mut H, members: &[PropType]| {
566:             members.len().hash(hasher);
567:             members.iter().for_each(|member| member.structural_hash(hasher));
568:         };
569:         match self {
570:             PropType::String
571:             | PropType::Number
572:             | PropType::Boolean
573:             | PropType::Null
574:             | PropType::Undefined
575:             | PropType::Any
576:             | PropType::Never
577:             | PropType::Unknown
578:             | PropType::Void
579:             | PropType::BigInt
580:             | PropType::ReactNode
581:             | PropType::CssProperties
582:             | PropType::ElementType
583:             | PropType::SxProps => {}
584:             PropType::StringLiteral(s) => s.hash(hasher),
585:             PropType::NumberLiteral(n) => n.to_bits().hash(hasher),
586:             PropType::BoolLiteral(b) => b.hash(hasher),
587:             PropType::BigIntLiteral(value) => value.as_str().hash(hasher),
588:             PropType::UniqueSymbol { name } => name.hash(hasher),
589:             PropType::EnumMember { enum_name, member, value } => {
590:                 enum_name.hash(hasher);
591:                 member.hash(hasher);
592:                 match value {
593:                     EnumMemberValue::String(s) => s.hash(hasher),
594:                     EnumMemberValue::Number(n) => n.to_bits().hash(hasher),
595:                 }
596:             }
597:             PropType::TemplateLiteral(parts) => {
598:                 parts.len().hash(hasher);
599:                 for part in parts {
600:                     match part {
601:                         TemplatePart::Text(text) => text.hash(hasher),
602:                         TemplatePart::Type(ty) => ty.structural_hash(hasher),
603:                     }
604:                 }
605:             }
606:             PropType::Union(members) | PropType::Intersection(members) => all(hasher, members),
607:             PropType::Tuple(elements) => {
608:                 elements.len().hash(hasher);
609:                 for element in elements {
610:                     element.kind.hash(hasher);
611:                     element.label.hash(hasher);
612:                     element.element_type.structural_hash(hasher);
613:                 }
614:             }
615:             PropType::Array(inner) | PropType::Readonly(inner) => inner.structural_hash(hasher),
616:             PropType::Object(fields) => hash_fields(fields, hasher),
617:             PropType::Callable { signatures, fields } => {
618:                 signatures.len().hash(hasher);
619:                 for signature in signatures {
620:                     signature.kind.hash(hasher);
621:                     hash_signature(&signature.type_params, &signature.params, &signature.return_type, hasher);
622:                 }
623:                 hash_fields(fields, hasher);
624:             }
625:             PropType::Named { name, args } | PropType::Recursive { name, args } => {
626:                 name.hash(hasher);
627:                 all(hasher, args);
628:             }
629:             PropType::Truncated { text, limit } => {
630:                 text.hash(hasher);
631:                 limit.hash(hasher);
632:             }
633:             PropType::Function { type_params, params, return_type } => {
634:                 hash_signature(type_params, params, return_type, hasher)
635:             }
636:             PropType::Ref { name, element } => {
637:                 name.hash(hasher);
638:                 element.hash(hasher);
639:             }
640:             PropType::HtmlAttributes { element, omitted } => {
641:                 element.hash(hasher);
642:                 omitted.hash(hasher);
643:             }
644:             PropType::LiteralUnion { members, has_default } => {
645:                 members.hash(hasher);
646:                 has_default.hash(hasher);
647:             }
648:             // Rare, and its reason has no cheap hash of its own.
649:             PropType::Opaque(detail) => {
650:                 detail.raw.hash(hasher);
651:                 format!("{:?}", detail.reason).hash(hasher);
652:             }
653:         }
654:     }
