127: /// Whether `answer`'s props are the structural ones because the checker had not answered within the wait: asked again
128: /// once the checker has answered, and before any source file changes, the session answers with the checker's props.
129: /// The one place that decides it, for hosts that show an answer and replace it later.
130: pub fn awaits_checker(answer: &ComponentAnswer) -> bool {
131:     answer.diagnostics.iter().any(|diagnostic| {
132:         diagnostic.code == DiagnosticCode::SemanticBackend
133:             && diagnostic.severity == DiagnosticSeverity::Info
134:             && diagnostic.message == CHECKER_PENDING
135:     })
136: }
