60: fn string_mapping(name: &str, value: &str) -> Option<String> {
61:     let mut chars = value.chars();
62:     match name {
63:         "Uppercase" => Some(value.to_uppercase()),
64:         "Lowercase" => Some(value.to_lowercase()),
65:         "Capitalize" => Some(chars.next().map(|first| first.to_uppercase().chain(chars).collect()).unwrap_or_default()),
66:         "Uncapitalize" => {
67:             Some(chars.next().map(|first| first.to_lowercase().chain(chars).collect()).unwrap_or_default())
68:         }
69:         _ => None,
70:     }
