46: /// A template literal's parts as a pattern: its text pieces, and each hole's type read by `read`.
47: pub(super) fn template_of(parts: &[CollectedType], mut read: impl FnMut(&CollectedType) -> PropType) -> PropType {
48:     PropType::TemplateLiteral(
49:         parts
50:             .iter()
51:             .map(|part| match part {
52:                 CollectedType::StringLiteral(text) => TemplatePart::Text(text.to_string()),
53:                 hole => TemplatePart::Type(read(hole)),
54:             })
55:             .collect(),
56:     )
